-- Tables (moved into private; protected-reference tables formerly in the prototype evidence schema)
CREATE TABLE private.bpay_protected_reference_events_v1 (
  family_id uuid NOT NULL,
  ordinal bigint NOT NULL,
  approval_id uuid NOT NULL,
  approval_hash bytea NOT NULL,
  active boolean NOT NULL,
  previous_digest bytea NOT NULL,
  digest bytea NOT NULL
