  timesheet_id uuid NOT NULL,
  family_id uuid NOT NULL,
  authorisation_at timestamp with time zone,
  consumed_at timestamp with time zone
);
alter table private.bpay_protected_reference_events_v1 owner to postgres;
revoke all on private.bpay_protected_reference_events_v1 from public,anon,authenticated,service_role;
