END) STORED;
-- [Worker AU amendment REL-GENCOL] keep the values the rewrite above stored; from here on the trigger below maintains them.
ALTER TABLE public.timesheets ALTER COLUMN bpay_work_key_v1 DROP EXPRESSION;
