-- Constraints (primary/unique, check, foreign key)
-- [Worker AI amendment] Every new CHECK/FOREIGN KEY on a pre-existing public table is added NOT VALID (brief lock, no
-- scan; still enforced for every new write) and validated by the backfill under SHARE UPDATE EXCLUSIVE. The
-- pay_finance_case_components pair (bpay_finance_component_work_presence_v1 / _reference_v1) is not added here: old
-- code inserting a linked component between this migration and R4 would violate it. The backfill adds it (same text)
-- in COMPLETE mode, after R4 installed the maintaining trigger.
ALTER TABLE private.bpay_protected_reference_events_v1 ADD CONSTRAINT bpay_protected_reference_events_v1_pkey PRIMARY KEY (family_id, ordinal);
ALTER TABLE private.bpay_protected_reference_heads_v1 ADD CONSTRAINT bpay_protected_reference_heads_v1_pkey PRIMARY KEY (family_id);
ALTER TABLE private.bpay_clock_families_v1 ADD CONSTRAINT bpay_clock_families_v1_pkey PRIMARY KEY (id);
ALTER TABLE private.bpay_clock_rows_v1 ADD CONSTRAINT bpay_clock_rows_v1_pkey PRIMARY KEY (timesheet_id);
ALTER TABLE private.bpay_clock_families_v1 ADD CONSTRAINT bpay_clock_families_v1_booking_id_key UNIQUE (booking_id);
ALTER TABLE public.timesheets ADD CONSTRAINT bpay_timesheet_work_identity_v1 UNIQUE (timesheet_id, bpay_work_revision_v1);
ALTER TABLE private.bpay_protected_reference_events_v1 ADD CONSTRAINT bpay_protected_reference_events_v1_approval_hash_check CHECK ((octet_length(approval_hash) = 32));
ALTER TABLE private.bpay_protected_reference_events_v1 ADD CONSTRAINT bpay_protected_reference_events_v1_digest_check CHECK (((octet_length(previous_digest) = 32) AND (octet_length(digest) = 32)));
ALTER TABLE private.bpay_protected_reference_events_v1 ADD CONSTRAINT bpay_protected_reference_events_v1_ordinal_check CHECK ((ordinal > 0));
ALTER TABLE private.bpay_protected_reference_heads_v1 ADD CONSTRAINT bpay_protected_reference_heads_v1_digest_check CHECK ((octet_length(digest) = 32));
ALTER TABLE private.bpay_protected_reference_heads_v1 ADD CONSTRAINT bpay_protected_reference_heads_v1_ordinal_check CHECK ((ordinal >= 0));
-- [Worker CA amendment ORPHAN-V5] A pay item may record a Timesheet reference (item timesheet_id, else the UUID-shaped
-- frozen basis timesheet_id) whose Timesheet row no longer exists (hosted TEST: 165 such items). Today's code maps
-- that item to the recorded UUID and nothing else. The item trigger therefore stores the recorded UUID with key and
-- revision NULL. This CHECK admits exactly that shape: a revision needs a reference, and a key needs a revision.
ALTER TABLE public.pay_batch_items ADD CONSTRAINT bpay_item_work_reference_presence_v1 CHECK ((((bpay_direct_work_revision_v1 IS NULL) OR (bpay_direct_source_timesheet_id_v1 IS NOT NULL)) AND ((bpay_direct_work_key_v1 IS NULL) OR (bpay_direct_work_revision_v1 IS NOT NULL)))) NOT VALID;
ALTER TABLE public.weekly_source_root_authorisations ADD CONSTRAINT bpay_evidence_shape_v1 CHECK ((((bpay_evidence_codec_v1 = 1) AND (bpay_evidence_reference_v1 IS NULL)) OR ((bpay_evidence_codec_v1 = 2) AND (bpay_evidence_reference_v1 IS NOT NULL) AND (protected_decision_hashes IS NULL)))) NOT VALID;
ALTER TABLE private.bpay_protected_reference_events_v1 ADD CONSTRAINT bpay_protected_reference_events_v1_family_id_fkey FOREIGN KEY (family_id) REFERENCES private.bpay_protected_reference_heads_v1(family_id);
ALTER TABLE private.bpay_clock_rows_v1 ADD CONSTRAINT bpay_clock_rows_v1_family_id_fkey FOREIGN KEY (family_id) REFERENCES private.bpay_clock_families_v1(id);
ALTER TABLE private.bpay_clock_rows_v1 ADD CONSTRAINT bpay_clock_rows_v1_timesheet_id_fkey FOREIGN KEY (timesheet_id) REFERENCES public.timesheets(timesheet_id) ON DELETE CASCADE;
-- [Worker CA amendment ORPHAN-V5] MATCH SIMPLE (an orphan has a reference but no revision, so it is not checked) and
-- ON DELETE SET NULL (revision only): deleting a Timesheet keeps the recorded reference and clears only the live
-- revision, and the item trigger then clears the key. Today a Timesheet whose only pay-item reference is the frozen
-- UUID can be deleted; MATCH FULL with NO ACTION refused that delete, which would have been a behaviour change.
ALTER TABLE public.pay_batch_items ADD CONSTRAINT bpay_item_work_reference_v1 FOREIGN KEY (bpay_direct_source_timesheet_id_v1, bpay_direct_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) ON DELETE SET NULL (bpay_direct_work_revision_v1) NOT VALID;
ALTER TABLE public.timesheet_pay_state ADD CONSTRAINT bpay_timesheet_pay_state_work_fk FOREIGN KEY (timesheet_id, bpay_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
ALTER TABLE public.timesheet_payment_overrides ADD CONSTRAINT bpay_timesheet_payment_overrides_work_fk FOREIGN KEY (timesheet_id, bpay_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
ALTER TABLE public.timesheet_payment_overrides ADD CONSTRAINT timesheet_payment_overrides_bpay_clock_family_id_v1_fkey FOREIGN KEY (bpay_clock_family_id_v1) REFERENCES private.bpay_clock_families_v1(id) NOT VALID;
ALTER TABLE public.ts_pay_adjustments ADD CONSTRAINT bpay_ts_pay_adjustments_work_fk FOREIGN KEY (timesheet_id, bpay_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
ALTER TABLE public.weekly_exceptional_pay_target_families ADD CONSTRAINT bpay_protected_root_work_v1 FOREIGN KEY (root_timesheet_id, bpay_root_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
ALTER TABLE public.weekly_source_root_authorisations ADD CONSTRAINT bpay_authorisation_work_reference_v1 FOREIGN KEY (root_timesheet_id, bpay_root_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
ALTER TABLE public.weekly_source_row_timesheet_lineages ADD CONSTRAINT bpay_lineage_work_revision_fk_v1 FOREIGN KEY (timesheet_id, bpay_lineage_work_revision_v1) REFERENCES public.timesheets(timesheet_id, bpay_work_revision_v1) NOT VALID;
-- [Worker AU amendment REL-GENCOL] the former generation expression, as a constraint (validated by the backfill).
ALTER TABLE public.timesheets ADD CONSTRAINT bpay_timesheet_work_key_expression_v1 CHECK ((bpay_work_key_v1 IS NOT DISTINCT FROM
CASE
    WHEN ((booking_id IS NOT NULL) AND (btrim(booking_id) <> ''::text)) THEN booking_id
    ELSE NULL::text
END)) NOT VALID;

-- [Worker AU amendment REL-GENCOL] Maintaining trigger for timesheets.bpay_work_key_v1. It is installed here, not in a
-- repeatable, because the column must be maintained from the moment this migration commits (the backfill and old code
-- write in between). Always recomputed from the final booking_id: a whole-row copy or an explicit value cannot leave a
-- different key. Named zz_ so it fires after every other BEFORE trigger (booking_id is final, and earlier BEFORE
-- triggers see OLD's value on UPDATE rather than a changed key); ENABLE ALWAYS so session_replication_role=replica does
-- not skip it (a generated column was not skipped either). SECURITY INVOKER, owner-only EXECUTE.
CREATE FUNCTION private.bpay_timesheet_work_key_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
BEGIN
 NEW.bpay_work_key_v1:=CASE
   WHEN ((NEW.booking_id IS NOT NULL) AND (btrim(NEW.booking_id) <> ''::text)) THEN NEW.booking_id
   ELSE NULL::text
 END;
 RETURN NEW;
END;
$function$;
ALTER FUNCTION private.bpay_timesheet_work_key_v1() OWNER TO postgres;
REVOKE ALL ON FUNCTION private.bpay_timesheet_work_key_v1() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER zz_bpay_timesheet_work_key_v1 BEFORE INSERT OR UPDATE ON public.timesheets FOR EACH ROW EXECUTE FUNCTION private.bpay_timesheet_work_key_v1();
ALTER TABLE public.timesheets ENABLE ALWAYS TRIGGER zz_bpay_timesheet_work_key_v1;

-- A14 precondition: the A14 partial indexes rely on the status CHECK and NOT NULL columns
DO $a14$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.banking_pay_workbench_jobs'::regclass
      AND conname = 'banking_pay_workbench_jobs_status_chk'
      AND convalidated
      AND pg_get_constraintdef(oid) = 'CHECK ((status = ANY (ARRAY[''QUEUED''::text, ''RUNNING''::text, ''SUCCEEDED''::text, ''FAILED''::text, ''DEAD''::text])))'
  ) OR EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'public.banking_pay_workbench_jobs'::regclass AND attname IN ('status', 'dedupe_key') AND NOT attnotnull
  ) THEN
    RAISE EXCEPTION 'A14_WB_READERS_PRECONDITION_FAILED: banking_pay_workbench_jobs status CHECK / NOT NULL changed';
  END IF;
END
$a14$;

