  ON public.banking_pay_workbench_jobs USING btree (scope_change_generation)
  WHERE scope_change_generation IS NOT NULL AND job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT') AND status = 'SUCCEEDED' AND (candidate_id IS NULL OR job_type = 'CONTRACT_CLIENT_DIRTY_FANOUT');
-- piece A14
