  ON public.banking_pay_workbench_jobs USING btree (md5(BTRIM(dedupe_key)))
  WHERE scope_change_generation IS NOT NULL AND job_type IN ('WORKBENCH_CANDIDATE_DIRTY_APPLY', 'WORKBENCH_FINANCE_CASE_DIRTY_APPLY', 'CONTRACT_CLIENT_DIRTY_FANOUT') AND dedupe_key <> BTRIM(dedupe_key);

